INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0003-000000000001', '00000001-0000-0000-0000-000000000003', '00000000-0000-0000-0001-000000000001', 1, 'numeros-1-20', '{"es": "Números 1–20", "en": "Numbers 1–20"}'::jsonb, '{"es": "Aprende los números del 1 al 20 en inglés.", "en": "Learn the numbers from 1 to 20 in English."}'::jsonb, 'vocabulary', 15, 10, '{
  "intro": "Los números son una parte fundamental del inglés cotidiano. En esta lección aprenderás los números del 1 al 20, que son la base para todos los demás números en inglés.",
  "sections": [
    {"type": "table", "title": "NÚMEROS 1–10", "headers": ["Número", "Inglés", "Pronunciación"], "rows": [["1","one","/wʌn/"],["2","two","/tuː/"],["3","three","/θriː/"],["4","four","/fɔːr/"],["5","five","/faɪv/"],["6","six","/sɪks/"],["7","seven","/ˈsɛvən/"],["8","eight","/eɪt/"],["9","nine","/naɪn/"],["10","ten","/tɛn/"]]},
    {"type": "table", "title": "NÚMEROS 11–20", "headers": ["Número", "Inglés", "Pronunciación"], "rows": [["11","eleven","/ɪˈlɛvən/"],["12","twelve","/twɛlv/"],["13","thirteen","/ˌθɜːrˈtiːn/"],["14","fourteen","/ˌfɔːrˈtiːn/"],["15","fifteen","/ˌfɪfˈtiːn/"],["16","sixteen","/ˌsɪksˈtiːn/"],["17","seventeen","/ˌsɛvənˈtiːn/"],["18","eighteen","/ˌeɪˈtiːn/"],["19","nineteen","/ˌnaɪnˈtiːn/"],["20","twenty","/ˈtwɛnti/"]]},
    {"type": "examples", "title": "EJEMPLOS EN CONTEXTO", "items": [{"label": "EDAD", "en": "I am fifteen years old.", "es": "Tengo quince años."},{"label": "CANTIDAD", "en": "There are twelve students in the class.", "es": "Hay doce estudiantes en la clase."}]},
    {"type": "note", "variant": "info", "text": "Los números del 13 al 19 llevan el acento en la segunda sílaba: thirTEEN, fourTEEN. Esto los distingue de las decenas: THIRty, FOURty."}
  ]
}'::jsonb, true),
('00000002-0000-0000-0003-000000000002', '00000001-0000-0000-0000-000000000003', '00000000-0000-0000-0001-000000000001', 2, 'numeros-21-100', '{"es": "Números 21–100", "en": "Numbers 21–100"}'::jsonb, '{"es": "Aprende las decenas y los números compuestos hasta el 100.", "en": "Learn the tens and compound numbers up to 100."}'::jsonb, 'vocabulary', 15, 10, '{
  "intro": "Ahora que conoces los números del 1 al 20, aprenderás las decenas y cómo formar números compuestos. El patrón es muy regular.",
  "sections": [
    {"type": "table", "title": "LAS DECENAS", "headers": ["Número", "Inglés", "Pronunciación"], "rows": [["20","twenty","/ˈtwɛnti/"],["30","thirty","/ˈθɜːrti/"],["40","forty","/ˈfɔːrti/"],["50","fifty","/ˈfɪfti/"],["60","sixty","/ˈsɪksti/"],["70","seventy","/ˈsɛvənti/"],["80","eighty","/ˈeɪti/"],["90","ninety","/ˈnaɪnti/"],["100","one hundred","/wʌn ˈhʌndrəd/"]]},
    {"type": "explanation", "title": "NÚMEROS COMPUESTOS", "text": "Para formar números entre las decenas, une la decena con un guion y el número del 1 al 9. Por ejemplo: twenty-one (21), thirty-five (35), ninety-nine (99). El guion es obligatorio en inglés escrito."},
    {"type": "examples", "title": "EJEMPLOS", "items": [{"label": "21", "en": "twenty-one", "es": "veintiuno"},{"label": "55", "en": "fifty-five", "es": "cincuenta y cinco"},{"label": "99", "en": "ninety-nine", "es": "noventa y nueve"}]},
    {"type": "note", "variant": "warning", "text": "¡Cuidado! ''Forty'' se escribe sin ''u'', a diferencia de ''four''. Este es uno de los errores más comunes."}
  ]
}'::jsonb, true),
('00000002-0000-0000-0003-000000000003', '00000001-0000-0000-0000-000000000003', '00000000-0000-0000-0001-000000000001', 3, 'numeros-grandes', '{"es": "Números 100–1,000,000", "en": "Numbers 100–1,000,000"}'::jsonb, '{"es": "Aprende a expresar centenas, miles y millones en inglés.", "en": "Learn to express hundreds, thousands and millions in English."}'::jsonb, 'vocabulary', 15, 12, '{
  "intro": "En esta lección aprenderás a trabajar con números grandes: centenas, miles y millones. Estos números son esenciales para hablar de precios, poblaciones y estadísticas.",
  "sections": [
    {"type": "table", "title": "NÚMEROS GRANDES", "headers": ["Número", "Inglés"], "rows": [["100","one hundred"],["500","five hundred"],["1,000","one thousand"],["5,000","five thousand"],["100,000","one hundred thousand"],["1,000,000","one million"]]},
    {"type": "note", "variant": "warning", "text": "En inglés se usan comas para separar miles (1,000) y punto para los decimales (3.14), al contrario que en español."},
    {"type": "note", "variant": "info", "text": "''Billion'' en inglés americano significa mil millones (1,000,000,000), no un billón como en español."}
  ]
}'::jsonb, true),
('00000002-0000-0000-0003-000000000004', '00000001-0000-0000-0000-000000000003', '00000000-0000-0000-0001-000000000001', 4, 'numeros-ordinales', '{"es": "Números Ordinales", "en": "Ordinal Numbers"}'::jsonb, '{"es": "Aprende a usar los números ordinales para indicar orden y posición.", "en": "Learn ordinal numbers to indicate order and position."}'::jsonb, 'grammar', 15, 12, '{
  "intro": "Los números ordinales indican posición o rango: primero, segundo, tercero... Los tres primeros son irregulares; a partir del cuarto se añade -th.",
  "sections": [
    {"type": "table", "title": "ORDINALES DEL 1 AL 12", "headers": ["Número", "Ordinal", "Abrev."], "rows": [["1","first","1st"],["2","second","2nd"],["3","third","3rd"],["4","fourth","4th"],["5","fifth","5th"],["6","sixth","6th"],["7","seventh","7th"],["8","eighth","8th"],["9","ninth","9th"],["10","tenth","10th"],["11","eleventh","11th"],["12","twelfth","12th"]]},
    {"type": "examples", "title": "EJEMPLOS", "items": [{"label": "POSICIÓN", "en": "She finished first in the race.", "es": "Ella terminó primera en la carrera."},{"label": "FECHA", "en": "Today is the fifth of June.", "es": "Hoy es el cinco de junio."}]},
    {"type": "note", "variant": "tip", "text": "Irregularidades importantes: five→fifth, eight→eighth, nine→ninth, twelve→twelfth. Para las decenas: twenty→twentieth, thirty→thirtieth."}
  ]
}'::jsonb, true),
('00000002-0000-0000-0003-000000000005', '00000001-0000-0000-0000-000000000003', '00000000-0000-0000-0001-000000000001', 5, 'precios-cantidades', '{"es": "Precios y Cantidades", "en": "Prices and Quantities"}'::jsonb, '{"es": "Aprende a hablar de precios, dinero y cantidades en inglés.", "en": "Learn to talk about prices, money and quantities in English."}'::jsonb, 'vocabulary', 15, 12, '{
  "intro": "Saber hablar de precios y cantidades es esencial para hacer compras y manejar situaciones cotidianas en inglés.",
  "sections": [
    {"type": "explanation", "title": "PREGUNTAR EL PRECIO", "text": "''How much is it?'' (¿Cuánto cuesta?) es la pregunta más común. También: ''How much does it cost?''. Los precios se leen así: $5.99 = five dollars and ninety-nine cents, o informalmente: five ninety-nine."},
    {"type": "table", "title": "VOCABULARIO DE CANTIDADES", "headers": ["Inglés", "Español"], "rows": [["a dozen","una docena (12)"],["half a dozen","media docena (6)"],["a couple","un par / dos"],["a few","unos pocos"],["half","la mitad"],["a quarter","un cuarto"]]},
    {"type": "examples", "title": "EJEMPLOS", "items": [{"label": "PRECIO", "en": "How much is this shirt? It''s twenty-five dollars.", "es": "¿Cuánto cuesta esta camisa? Cuesta veinticinco dólares."},{"label": "CANTIDAD", "en": "I''d like a dozen eggs, please.", "es": "Quisiera una docena de huevos, por favor."}]},
    {"type": "note", "variant": "tip", "text": "Al hablar informalmente, los angloparlantes a menudo omiten ''dollars'': ''That''s five ninety-nine'' en lugar de ''five dollars and ninety-nine cents''."}
  ]
}'::jsonb, true);

INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0003-0001-0001-000000000001', '00000002-0000-0000-0003-000000000001', 1, 'flashcard', '{"text": "twelve", "subtext": "el número 12"}'::jsonb, '{"text": "doce", "phonetic": "/twɛlv/"}'::jsonb, NULL, NULL),
