('00000003-0003-0002-0001-000000000001', '00000002-0000-0000-0003-000000000002', 1, 'flashcard', '{"text": "thirty", "subtext": "el número 30"}'::jsonb, '{"text": "treinta", "phonetic": "/ˈθɜːrti/"}'::jsonb, NULL, NULL),
('00000003-0003-0002-0002-000000000001', '00000002-0000-0000-0003-000000000002', 2, 'flashcard', '{"text": "seventy-five", "subtext": "el número 75"}'::jsonb, '{"text": "setenta y cinco", "phonetic": "/ˈsɛvənti faɪv/"}'::jsonb, NULL, NULL),
('00000003-0003-0002-0003-000000000001', '00000002-0000-0000-0003-000000000002', 3, 'multiple_choice', '{"text": "¿Cómo se escribe ''40'' en inglés?"}'::jsonb, '{"text": "forty"}'::jsonb, '["fourty","forty-o","fourtie"]'::jsonb, '{"es": "''Forty'' se escribe sin ''u'', a diferencia de ''four''. Este es un error muy común."}'::jsonb),
('00000003-0003-0002-0004-000000000001', '00000002-0000-0000-0003-000000000002', 4, 'multiple_choice', '{"text": "¿Qué número es ''eighty-three''?"}'::jsonb, '{"text": "83"}'::jsonb, '["38","80","93"]'::jsonb, '{"es": "''Eighty'' es 80 y ''three'' es 3, por lo tanto ''eighty-three'' es 83."}'::jsonb),
('00000003-0003-0002-0005-000000000001', '00000002-0000-0000-0003-000000000002', 5, 'fill_blank', '{"text": "She is ___ years old. (56)"}'::jsonb, '{"text": "fifty-six", "accepted": ["fifty-six","fifty six","56"]}'::jsonb, NULL, NULL),
('00000003-0003-0002-0006-000000000001', '00000002-0000-0000-0003-000000000002', 6, 'fill_blank', '{"text": "There are ___ minutes in an hour. (60)"}'::jsonb, '{"text": "sixty", "accepted": ["sixty","60"]}'::jsonb, NULL, NULL),
('00000003-0003-0002-0007-000000000001', '00000002-0000-0000-0003-000000000002', 7, 'translation', '{"text": "Mi abuela tiene noventa y dos años."}'::jsonb, '{"text": "My grandmother is ninety-two years old.", "accepted": ["My grandmother is ninety-two years old","My grandmother is 92 years old"]}'::jsonb, NULL, NULL),
('00000003-0003-0002-0008-000000000001', '00000002-0000-0000-0003-000000000002', 8, 'translation', '{"text": "El autobús tiene cuarenta y siete asientos."}'::jsonb, '{"text": "The bus has forty-seven seats.", "accepted": ["The bus has forty-seven seats","The bus has 47 seats"]}'::jsonb, NULL, NULL),

('00000003-0003-0003-0001-000000000001', '00000002-0000-0000-0003-000000000003', 1, 'flashcard', '{"text": "one hundred", "subtext": "el número 100"}'::jsonb, '{"text": "cien / ciento", "phonetic": "/wʌn ˈhʌndrəd/"}'::jsonb, NULL, NULL),
('00000003-0003-0003-0002-000000000001', '00000002-0000-0000-0003-000000000003', 2, 'flashcard', '{"text": "one million", "subtext": "el número 1,000,000"}'::jsonb, '{"text": "un millón", "phonetic": "/wʌn ˈmɪljən/"}'::jsonb, NULL, NULL),
('00000003-0003-0003-0003-000000000001', '00000002-0000-0000-0003-000000000003', 3, 'multiple_choice', '{"text": "¿Cómo se dice ''5,000'' en inglés?"}'::jsonb, '{"text": "five thousand"}'::jsonb, '["five hundreds","five million","fifty hundred"]'::jsonb, '{"es": "1,000 = one thousand, por lo que 5,000 = five thousand."}'::jsonb),
('00000003-0003-0003-0004-000000000001', '00000002-0000-0000-0003-000000000003', 4, 'multiple_choice', '{"text": "¿Qué número es ''two hundred and fifty''?"}'::jsonb, '{"text": "250"}'::jsonb, '["25","2,050","2,500"]'::jsonb, '{"es": "''Two hundred'' es 200, más ''fifty'' que es 50, da 250."}'::jsonb),
('00000003-0003-0003-0005-000000000001', '00000002-0000-0000-0003-000000000003', 5, 'fill_blank', '{"text": "The stadium holds fifty ___ people. (50,000)"}'::jsonb, '{"text": "thousand", "accepted": ["thousand"]}'::jsonb, NULL, NULL),
('00000003-0003-0003-0006-000000000001', '00000002-0000-0000-0003-000000000003', 6, 'fill_blank', '{"text": "The population is two ___. (2,000,000)"}'::jsonb, '{"text": "million", "accepted": ["million"]}'::jsonb, NULL, NULL),
('00000003-0003-0003-0007-000000000001', '00000002-0000-0000-0003-000000000003', 7, 'translation', '{"text": "El estadio tiene capacidad para cincuenta mil personas."}'::jsonb, '{"text": "The stadium holds fifty thousand people.", "accepted": ["The stadium holds fifty thousand people","The stadium has a capacity for fifty thousand people"]}'::jsonb, NULL, NULL),
('00000003-0003-0003-0008-000000000001', '00000002-0000-0000-0003-000000000003', 8, 'translation', '{"text": "El libro cuesta trescientos dólares."}'::jsonb, '{"text": "The book costs three hundred dollars.", "accepted": ["The book costs three hundred dollars","The book is three hundred dollars"]}'::jsonb, NULL, NULL),

('00000003-0003-0004-0001-000000000001', '00000002-0000-0000-0003-000000000004', 1, 'flashcard', '{"text": "first", "subtext": "posición número 1"}'::jsonb, '{"text": "primero / primera", "phonetic": "/fɜːrst/"}'::jsonb, NULL, NULL),
('00000003-0003-0004-0002-000000000001', '00000002-0000-0000-0003-000000000004', 2, 'flashcard', '{"text": "third", "subtext": "posición número 3"}'::jsonb, '{"text": "tercero / tercera", "phonetic": "/θɜːrd/"}'::jsonb, NULL, NULL),
('00000003-0003-0004-0003-000000000001', '00000002-0000-0000-0003-000000000004', 3, 'multiple_choice', '{"text": "¿Cuál es el ordinal de ''5''?"}'::jsonb, '{"text": "fifth"}'::jsonb, '["fiveth","fifthth","fived"]'::jsonb, '{"es": "5 → fifth. La ''ve'' de ''five'' cambia a ''f'': five → fifth."}'::jsonb),
('00000003-0003-0004-0004-000000000001', '00000002-0000-0000-0003-000000000004', 4, 'multiple_choice', '{"text": "¿Cómo se abrevia el ordinal ''second''?"}'::jsonb, '{"text": "2nd"}'::jsonb, '["2st","2th","2rd"]'::jsonb, '{"es": "''Second'' se abrevia como 2nd. Las abreviaturas de ordinales usan las dos últimas letras de la palabra."}'::jsonb),
('00000003-0003-0004-0005-000000000001', '00000002-0000-0000-0003-000000000004', 5, 'fill_blank', '{"text": "January is the ___ month of the year."}'::jsonb, '{"text": "first", "accepted": ["first","1st"]}'::jsonb, NULL, NULL),
('00000003-0003-0004-0006-000000000001', '00000002-0000-0000-0003-000000000004', 6, 'fill_blank', '{"text": "December is the ___ month of the year."}'::jsonb, '{"text": "twelfth", "accepted": ["twelfth","12th"]}'::jsonb, NULL, NULL),
('00000003-0003-0004-0007-000000000001', '00000002-0000-0000-0003-000000000004', 7, 'translation', '{"text": "Ella terminó en tercer lugar en la competencia."}'::jsonb, '{"text": "She finished in third place in the competition.", "accepted": ["She finished in third place in the competition","She came third in the competition"]}'::jsonb, NULL, NULL),
('00000003-0003-0004-0008-000000000001', '00000002-0000-0000-0003-000000000004', 8, 'translation', '{"text": "Mi apartamento está en el octavo piso."}'::jsonb, '{"text": "My apartment is on the eighth floor.", "accepted": ["My apartment is on the eighth floor","My flat is on the eighth floor"]}'::jsonb, NULL, NULL),

('00000003-0003-0005-0001-000000000001', '00000002-0000-0000-0003-000000000005', 1, 'flashcard', '{"text": "How much is it?", "subtext": "preguntando el precio"}'::jsonb, '{"text": "¿Cuánto cuesta?", "phonetic": "/haʊ mʌtʃ ɪz ɪt/"}'::jsonb, NULL, NULL),
('00000003-0003-0005-0002-000000000001', '00000002-0000-0000-0003-000000000005', 2, 'flashcard', '{"text": "a dozen", "subtext": "cantidad"}'::jsonb, '{"text": "una docena (12 unidades)", "phonetic": "/ə ˈdʌzən/"}'::jsonb, NULL, NULL),
('00000003-0003-0005-0003-000000000001', '00000002-0000-0000-0003-000000000005', 3, 'multiple_choice', '{"text": "¿Cómo se lee el precio ''$7.50'' en inglés?"}'::jsonb, '{"text": "seven dollars and fifty cents"}'::jsonb, '["seven fifty dollars","seven and fifty","seven dollars fifty pence"]'::jsonb, '{"es": "Los precios se leen con ''dollars'' y ''cents''. $7.50 = seven dollars and fifty cents."}'::jsonb),
('00000003-0003-0005-0004-000000000001', '00000002-0000-0000-0003-000000000005', 4, 'multiple_choice', '{"text": "¿Qué significa ''half price''?"}'::jsonb, '{"text": "a mitad de precio"}'::jsonb, '["precio completo","precio doble","precio especial"]'::jsonb, '{"es": "''Half'' significa mitad, por lo que ''half price'' es un 50% de descuento."}'::jsonb),
('00000003-0003-0005-0005-000000000001', '00000002-0000-0000-0003-000000000005', 5, 'fill_blank', '{"text": "I need ___ eggs for the recipe. (12)"}'::jsonb, '{"text": "a dozen", "accepted": ["a dozen","twelve","12"]}'::jsonb, NULL, NULL),
('00000003-0003-0005-0006-000000000001', '00000002-0000-0000-0003-000000000005', 6, 'fill_blank', '{"text": "___ is this jacket? It''s forty-nine ninety-nine."}'::jsonb, '{"text": "How much", "accepted": ["How much"]}'::jsonb, NULL, NULL),
('00000003-0003-0005-0007-000000000001', '00000002-0000-0000-0003-000000000005', 7, 'translation', '{"text": "¿Cuánto cuestan estos zapatos?"}'::jsonb, '{"text": "How much are these shoes?", "accepted": ["How much are these shoes","How much do these shoes cost"]}'::jsonb, NULL, NULL),
('00000003-0003-0005-0008-000000000001', '00000002-0000-0000-0003-000000000005', 8, 'translation', '{"text": "Quisiera medio kilo de queso, por favor."}'::jsonb, '{"text": "I would like half a kilo of cheese, please.", "accepted": ["I would like half a kilo of cheese please","I''d like half a kilo of cheese, please"]}'::jsonb, NULL, NULL);

-- Module 4: Fechas y Tiempo lessons
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0004-000000000001', '00000001-0000-0000-0000-000000000004', '00000000-0000-0000-0001-000000000001', 1, 'dias-semana', '{"es": "Los Días de la Semana", "en": "Days of the Week"}'::jsonb, '{"es": "Aprende los días de la semana en inglés.", "en": "Learn the days of the week in English."}'::jsonb, 'vocabulary', 15, 10, '{
  "intro": "Los días de la semana son esenciales en inglés. Siempre se escriben con mayúscula y sus nombres tienen origen en la mitología nórdica y romana.",
  "sections": [
    {"type": "table", "title": "LOS 7 DÍAS", "headers": ["Inglés", "Español", "Pronunciación"], "rows": [["Monday","lunes","/ˈmʌndeɪ/"],["Tuesday","martes","/ˈtjuːzdeɪ/"],["Wednesday","miércoles","/ˈwɛnzdeɪ/"],["Thursday","jueves","/ˈθɜːrzdeɪ/"],["Friday","viernes","/ˈfraɪdeɪ/"],["Saturday","sábado","/ˈsætərdeɪ/"],["Sunday","domingo","/ˈsʌndeɪ/"]]},
    {"type": "explanation", "title": "WEEKDAYS VS WEEKEND", "text": "Los días de lunes a viernes se llaman ''weekdays'' (días laborables). Sábado y domingo forman el ''weekend'' (fin de semana)."},
    {"type": "note", "variant": "warning", "text": "''Wednesday'' se pronuncia /ˈwɛnzdeɪ/ — la ''d'' del medio es silenciosa. La preposición con los días es ''on'': ''on Monday'', ''on Tuesdays'' (habitual)."}
  ]
}'::jsonb, true),
('00000002-0000-0000-0004-000000000002', '00000001-0000-0000-0000-000000000004', '00000000-0000-0000-0001-000000000001', 2, 'meses-ano', '{"es": "Los Meses del Año", "en": "Months of the Year"}'::jsonb, '{"es": "Aprende los doce meses del año en inglés.", "en": "Learn the twelve months of the year in English."}'::jsonb, 'vocabulary', 15, 10, '{
  "intro": "Los doce meses del año en inglés siempre se escriben con mayúscula. Se usan con la preposición ''in'': in January, in March.",
  "sections": [
    {"type": "table", "title": "LOS 12 MESES", "headers": ["Mes", "Inglés", "Abrev."], "rows": [["1","January","Jan."],["2","February","Feb."],["3","March","Mar."],["4","April","Apr."],["5","May","May"],["6","June","Jun."],["7","July","Jul."],["8","August","Aug."],["9","September","Sep."],["10","October","Oct."],["11","November","Nov."],["12","December","Dec."]]},
    {"type": "note", "variant": "info", "text": "En inglés americano las fechas se escriben mes/día/año: 01/15/2025 = January 15, 2025. En inglés británico es día/mes/año: 15/01/2025."}
  ]
}'::jsonb, true),
('00000002-0000-0000-0004-000000000003', '00000001-0000-0000-0000-000000000004', '00000000-0000-0000-0001-000000000001', 3, 'estaciones', '{"es": "Las Estaciones del Año", "en": "Seasons of the Year"}'::jsonb, '{"es": "Aprende las estaciones y vocabulario del clima.", "en": "Learn the seasons and weather vocabulary."}'::jsonb, 'vocabulary', 15, 12, '{
  "intro": "Las cuatro estaciones y el vocabulario del clima son temas de conversación muy comunes en inglés, especialmente en el Reino Unido.",
  "sections": [
    {"type": "table", "title": "LAS ESTACIONES", "headers": ["Inglés", "Español", "Meses"], "rows": [["spring","primavera","March, April, May"],["summer","verano","June, July, August"],["fall / autumn","otoño","September, October, November"],["winter","invierno","December, January, February"]]},
    {"type": "table", "title": "VOCABULARIO DEL CLIMA", "headers": ["Inglés", "Español"], "rows": [["sunny","soleado"],["cloudy","nublado"],["rainy","lluvioso"],["windy","ventoso"],["hot","caliente"],["cold","frío"],["warm","cálido"],["foggy","neblinoso"]]},
    {"type": "note", "variant": "info", "text": "Para hablar del clima: ''It''s sunny'' (está soleado), ''It''s raining'' (está lloviendo), ''It''s cold'' (hace frío). El sujeto impersonal ''it'' no tiene traducción directa al español."}
  ]
}'::jsonb, true),
('00000002-0000-0000-0004-000000000004', '00000001-0000-0000-0000-000000000004', '00000000-0000-0000-0001-000000000001', 4, 'decir-hora', '{"es": "Decir la Hora", "en": "Telling the Time"}'::jsonb, '{"es": "Aprende a decir y preguntar la hora en inglés.", "en": "Learn to tell and ask the time in English."}'::jsonb, 'grammar', 15, 15, '{
  "intro": "Saber decir la hora en inglés es esencial para la vida diaria. Hay dos métodos: el digital (más simple) y el tradicional con ''past'' y ''to''.",
  "sections": [
    {"type": "table", "title": "CÓMO DECIR LA HORA", "headers": ["Hora", "Método tradicional", "Método digital"], "rows": [["3:00","It''s three o''clock","It''s three"],["3:15","It''s quarter past three","It''s three fifteen"],["3:30","It''s half past three","It''s three thirty"],["3:45","It''s quarter to four","It''s three forty-five"],["3:10","It''s ten past three","It''s three ten"]]},
    {"type": "explanation", "title": "AM Y PM", "text": "En inglés se usa el sistema de 12 horas con a.m. (antes del mediodía) y p.m. (después del mediodía). ''Noon'' = mediodía, ''midnight'' = medianoche."},
    {"type": "note", "variant": "tip", "text": "El método digital es más fácil para principiantes. ''It''s three thirty'' es completamente natural. ''O''clock'' solo se usa para horas exactas (sin minutos)."}
  ]
}'::jsonb, true),
('00000002-0000-0000-0004-000000000005', '00000001-0000-0000-0000-000000000004', '00000000-0000-0000-0001-000000000001', 5, 'hablar-fechas', '{"es": "Hablar de Fechas", "en": "Talking About Dates"}'::jsonb, '{"es": "Aprende a expresar y preguntar fechas completas.", "en": "Learn to express and ask about complete dates."}'::jsonb, 'grammar', 15, 12, '{
  "intro": "Hablar de fechas es esencial para hacer citas, planear eventos y hablar de cumpleaños. La preposición correcta es clave.",
  "sections": [
    {"type": "table", "title": "PREPOSICIONES CON TIEMPO", "headers": ["Preposición", "Uso", "Ejemplo"], "rows": [["on","días y fechas específicas","on Monday / on January 15th"],["in","meses, años, estaciones","in January / in 2025 / in spring"],["at","horas específicas","at 3 o''clock / at noon"]]},
    {"type": "examples", "title": "EJEMPLOS DE FECHAS", "items": [{"label": "AMERICANO", "en": "Today is March 21st, 2025.", "es": "Hoy es el 21 de marzo de 2025."},{"label": "PREGUNTA", "en": "What''s the date today? It''s the fifth of June.", "es": "¿Cuál es la fecha hoy? Es el cinco de junio."}]},
    {"type": "note", "variant": "tip", "text": "Regla mnemotécnica AT-ON-IN: AT para horas (at 5 pm), ON para días y fechas (on Monday), IN para periodos más largos (in June, in 2025)."}
  ]
}'::jsonb, true);

